begin;
with j as (select * from jsonb_to_recordset($law7d0035$[{"code_id":"BK_RF","article_number":"62","version_date":"1998-07-31","article_text":"Неналоговые доходы местных бюджетов формируются в соответствии со статьями 41,  42,  46,  58,  63 и 631 настоящего Кодекса,  в том числе за счет: (В редакции Федерального закона от 02.08.2019 № 307-ФЗ)\n\nдоходов от использования имущества,  находящегося в муниципальной собственности,  за исключением имущества муниципальных бюджетных и автономных учреждений,  а также имущества муниципальных унитарных предприятий,  в том числе казенных,  - по нормативу 100 процентов; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nдоходов от продажи имущества (кроме акций и иных форм участия в капитале) ,  находящегося в муниципальной собственности,  за исключением движимого имущества муниципальных бюджетных и автономных учреждений,  а также имущества муниципальных унитарных предприятий,  в том числе казенных,  - по нормативу 100 процентов; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 28.12.2013 № 418-ФЗ)\n\nдоходов от платных услуг,  оказываемых муниципальными казенными учреждениями; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nчасти прибыли муниципальных унитарных предприятий,  остающейся после уплаты налогов и иных обязательных платежей,  в размерах,  определяемых в порядке,  установленном муниципальными правовыми актами представительных органов муниципальных образований;\n\nплаты за использование лесов,  расположенных на землях,  находящихся в муниципальной собственности,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nплаты за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  находящихся в муниципальной собственности,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)\n\nплаты по соглашениям об установлении сервитута,  заключенным государственными (муниципальными)  органами,  единым институтом развития в жилищной сфере,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  находящихся в муниципальной собственности,  или земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах муниципальных округов,  городских округов,  городских округов с внутригородским делением,  городских,  сельских поселений,  - по нормативу 100 процентов в бюджет муниципального образования,  в собственности (на территории)  которого находится земельный участок,  если иное не установлено настоящей статьей; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)  (В редакции федеральных законов от 29.12.2015 № 406-ФЗ,  от 03.07.2016 № 345-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nплаты за публичный сервитут,  предусмотренной решением уполномоченного органа об установлении публичного сервитута в отношении земельных участков,  находящихся в муниципальной собственности,  или земельных участков,  государственная собственность на которые не разграничена,  которые расположены в границах муниципальных округов,  городских округов,  городских округов с внутригородским делением,  городских,  сельских поселений и не предоставлены гражданам или юридическим лицам (за исключением органов государственной власти (государственных органов) ,  органов местного самоуправления (муниципальных органов) ,  органов управления государственными внебюджетными фондами и казенных учреждений) ,  - по нормативу 100 процентов в бюджет муниципального образования,  в собственности (на территории)  которого находится земельный участок,  если иное не установлено настоящей статьей. (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nВ бюджеты муниципальных районов,  бюджеты муниципальных округов,  бюджеты городских округов и бюджеты городских округов с внутригородским делением подлежит зачислению плата за негативное воздействие на окружающую среду по нормативу 60 процентов. (В редакции федеральных законов от 03.12.2012 № 244-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 15.04.20\n\nтуристического налога - по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n2. В бюджеты городских округов с внутригородским делением подлежат зачислению налоговые доходы от следующих федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами:\n\nналога на доходы физических лиц (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом,  тридцать шестом,  тридцать девятом и пятьдесят седьмом статьи 50 настоящего Кодекса и абзацах восьмом - четырнадцатом настоящего пункта)  - по нормативу 15 процентов; (В редакции  федеральных законов от 15.10.2020 № 327-ФЗ,  от 01.07.2021 № 251-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nединого налога на вмененный доход для отдельных видов деятельности - по нормативу 100 процентов;\n\nединого сельскохозяйственного налога - по нормативу 100 процентов;\n\nгосударственной пошлины - в соответствии с пунктом 2 статьи 611 настоящего Кодекса;\n\nналога,  взимаемого в связи с применением патентной системы налогообложения,  - по нормативу 100 процентов;\n\nабзац. (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)  (Утратил силу  - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей и составляющей не более 5 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двенадцатом настоящего пункта) ,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 702 тысячи рублей,  относящейся к части налоговой базы,  превышающей 5 миллионов рублей и составляющей не более 20 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двенадцатом настоящего пункта) ,  - по нормативу 11 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 3402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 20 миллионов рублей и составляющей не более 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двенадцатом настоящего пункта) ,  - по нормативу 10 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 9402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двенадцатом настоящего пункта) ,  - по нормативу 9 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 6 статьи 210 Налогового кодекса Российской Федерации,  превышающей 2, 4 миллиона рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом и тридцать шестом статьи 50 настоящего Кодекса) ,  а также налога на доходы физических лиц в отношении доходов физических лиц,  не являющихся налоговыми резидентами Российской Федерации,  указанных в абзаце девятом пункта 3 статьи 224 Налогового кодекса Российской Федерации,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  а также налога на доходы физических лиц в части суммы налога,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце четырнадцатом настоящего пункта) ,  - по нормативу 15 процентов;  (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  а также налога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  - по нормативу 13 процентов. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n3. В бюджеты городских округов с внутригородским делением подлежат зачислению налоговые доходы от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов по единым нормативам отчислений,  установленным законами субъектов Российской Федерации для зачисления соответствующих налоговых доходов в бюджеты городских округов с внутригородским делением в соответствии с пунктом 1 статьи 58 настоящего Кодекса. В бюджеты городских округов с внутригородским делением подлежат зачислению налоговые доходы от налога на доходы физических лиц по дополнительным нормативам отчислений,  установленным органами государственной власти субъектов Российской Федерации в соответствии с пунктами 2 и 3 статьи 58 настоящего Кодекса.\n\n4. Налоговые доходы,  предусмотренные пунктом 2 настоящей статьи,  подлежащие зачислению в бюджет городского округа с внутригородским делением,  могут быть переданы полностью или частично органами государственной власти субъекта Российской Федерации в соответствии с законом субъекта Российской Федерации в бюджеты внутригородских районов по единым для всех внутригородских районов нормативам отчислений.\n\n5. Установленные настоящим Кодексом источники доходов бюджетов городских округов с внутригородским делением,  не отнесенные законами субъектов Российской Федерации к источникам доходов бюджетов внутригородских районов,  подлежат зачислению в бюджеты городских округов с внутригородским делением.\n\n(Дополнение статьей - Федеральный закон от 29.11.2014 № 383-ФЗ)","article_title":"Статья 62. Неналоговые доходы местных бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8df42c9cf2e00849a182ba6bb9789ef6678f5d7dfdda46c17080161939b941a"},{"code_id":"BK_RF","article_number":"63","version_date":"1998-07-31","article_text":"(Наименование в редакции федеральных законов от 26.04.2007 № 63-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 02.08.2019 № 307-ФЗ)\n\nМуниципальным правовым актом представительного органа муниципального района (за исключением решения о бюджете муниципального района или иного решения на ограниченный срок действия)  могут быть установлены единые для всех городских поселений муниципального района нормативы отчислений в бюджеты городских поселений от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  региональных и (или)  местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и (или)  законом субъекта Российской Федерации в бюджет муниципального района. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 29.11.2014 № 383-ФЗ)\n\nМуниципальным правовым актом представительного органа муниципального района (за исключением решения о бюджете муниципального района или иного решения на ограниченный срок действия)  могут быть установлены единые для всех сельских поселений муниципального района нормативы отчислений в бюджеты сельских поселений от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  региональных и (или)  местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и (или)  законом субъекта Российской Федерации в бюджет муниципального района. (Дополнение частью - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nМуниципальным правовым актом представительного органа муниципального района (за исключением решения о бюджете муниципального района или иного решения на ограниченный срок действия)  могут быть установлены единые для всех городских поселений муниципального района нормативы отчислений в бюджеты городских поселений от следующих неналоговых доходов,  подлежащих зачислению в бюджет муниципального района:\n\nденежные взыскания (штрафы) ,  предусмотренные Кодексом Российской Федерации об административных правонарушениях,  законами субъектов Российской Федерации об административных правонарушениях;\n\nплата за негативное воздействие на окружающую среду;\n\nплата от передачи в аренду земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах городских поселений,  а также средства от продажи прав на заключение договоров аренды указанных земельных участков.\n\n(Дополнение частью - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nМуниципальным правовым актом представительного органа муниципального района (за исключением решения о бюджете муниципального района или иного решения на ограниченный срок действия)  могут быть установлены единые для всех сельских поселений муниципального района нормативы отчислений в бюджеты сельских поселений от следующих неналоговых доходов,  подлежащих зачислению в бюджет муниципального района:\n\nденежные взыскания (штрафы) ,  предусмотренные Кодексом Российской Федерации об административных правонарушениях,  законами субъектов Российской Федерации об административных правонарушениях;\n\nплата за негативное воздействие на окружающую среду;\n\nплата от передачи в аренду земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах сельских поселений,  а также средства от продажи прав на заключение договоров аренды указанных земельных участков.\n\n(Дополнение частью - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 63. Полномочия муниципального района по установлению нормативов отчислений от федеральных,  региональных и местных налогов и сборов,  неналоговых доходов в бюджеты городских,  сельских поселений","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b9ce486f090cb5bc4d06e8fb3b1b0e02a09b2aa5ed206aa8df93dc5befb69a8f"},{"code_id":"BK_RF","article_number":"63.1","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 02.08.2019 № 307-ФЗ)\n\n1. Муниципальным правовым актом представительного органа городского округа с внутригородским делением (за исключением решения о бюджете городского округа с внутригородским делением или иного решения на ограниченный срок действия)  могут быть установлены единые для всех внутригородских районов городского округа с внутригородским делением нормативы отчислений в бюджеты внутригородских районов от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  региональных и (или)  местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и (или)  законом субъекта Российской Федерации в бюджет городского округа с внутригородским делением. (В редакции Федерального закона от 02.08.2019 № 307-ФЗ)\n\n2. Муниципальным правовым актом представительного органа городского округа с внутригородским делением (за исключением решения о бюджете городского округа с внутригородским делением или иного решения на ограниченный срок действия)  могут быть установлены единые для всех внутригородских районов городского округа с внутригородским делением нормативы отчислений в бюджеты внутригородских районов от следующих неналоговых доходов,  подлежащих зачислению в бюджет городского округа с внутригородским делением:\n\n1)  денежные взыскания (штрафы) ,  предусмотренные Кодексом Российской Федерации об административных правонарушениях,  законами субъектов Российской Федерации об административных правонарушениях;\n\n2)  плата за негативное воздействие на окружающую среду;\n\n3)  плата от передачи в аренду земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах городского округа с внутригородским делением,  а также средства от продажи прав на заключение договоров аренды указанных земельных участков.\n\n(Дополнение пунктом - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.11.2014 № 383-ФЗ)","article_title":"Статья 63.1. Полномочия городского округа с внутригородским делением по установлению нормативов отчислений от федеральных,  региональных и местных налогов и сборов,  неналоговых доходов в бюджеты внутригородских районов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7c721a35c2474fa6a92129a13b365e31094781673f45444cd83f0f52c24c494"},{"code_id":"BK_RF","article_number":"64","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 31.07.2020 № 263-ФЗ)","article_title":"Статья 64.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"277a000d1bab1af9bc5f7c081b8d78bbbd98a11906d6f3d1787d9722e0953934"},{"code_id":"BK_RF","article_number":"65","version_date":"1998-07-31","article_text":"Формирование расходов бюджетов бюджетной системы Российской Федерации осуществляется в соответствии с расходными обязательствами,  обусловленными установленным законодательством Российской Федерации разграничением полномочий федеральных органов государственной власти,  органов государственной власти субъектов Российской Федерации и органов местного самоуправления,  исполнение которых согласно законодательству Российской Федерации,  международным и иным договорам и соглашениям должно происходить в очередном финансовом году (очередном финансовом году и плановом периоде)  за счет средств соответствующих бюджетов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 65. Формирование расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b8056d9e5f2441f5b363e3b621a1c886143a5c20066a80e586eee0a919e70853"},{"code_id":"BK_RF","article_number":"66","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 66.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"67","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 67.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"68","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 68.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"69","version_date":"1998-07-31","article_text":"К бюджетным ассигнованиям относятся ассигнования на:\n\nоказание государственных (муниципальных)  услуг (выполнение работ) ,  включая ассигнования на закупки товаров,  работ,  услуг для обеспечения государственных (муниципальных)  нужд; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nсоциальное обеспечение населения;\n\nпредоставление бюджетных инвестиций юридическим лицам,  не являющимся государственными (муниципальными)  учреждениями и государственными (муниципальными)  унитарными предприятиями; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nпредоставление субсидий юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям) ,  индивидуальным предпринимателям,  физическим лицам; (В редакции Федерального закона от 23.07.2013 № 252-ФЗ)\n\nпредоставление межбюджетных трансфертов;\n\nпредоставление платежей,  взносов,  безвозмездных перечислений субъектам международного права;\n\nобслуживание государственного (муниципального)  долга;\n\nисполнение судебных актов по искам к Российской Федерации,  субъектам Российской Федерации,  муниципальным образованиям о возмещении вреда,  причиненного гражданину или юридическому лицу в результате незаконных действий (бездействия)  органов государственной власти (государственных органов) ,  органов местного самоуправления либо должностных лиц этих органов.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 69. Бюджетные ассигнования","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3521ed51f3d8d77d12a0931e195fb73702f64a294e24fc33c0866c7132796236"},{"code_id":"BK_RF","article_number":"69.1","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\nК бюджетным ассигнованиям на оказание государственных (муниципальных)  услуг (выполнение работ)  относятся ассигнования на: (В редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\nобеспечение выполнения функций казенных учреждений,  в том числе по оказанию государственных (муниципальных)  услуг (выполнению работ)  физическим и (или)  юридическим лицам; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпредоставление субсидий бюджетным и автономным учреждениям,  включая субсидии на финансовое обеспечение выполнения ими государственного (муниципального)  задания; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nпредоставление субсидий некоммерческим организациям,  не являющимся государственными (муниципальными)  учреждениями,  в том числе в соответствии с договорами (соглашениями)  на оказание указанными организациями государственных (муниципальных)  услуг (выполнение работ)  физическим и (или)  юридическим лицам; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nосуществление бюджетных инвестиций в объекты государственной (муниципальной)  собственности; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)  (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nзакупку товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд (за исключением бюджетных ассигнований для обеспечения выполнения функций казенного учреждения и бюджетных ассигнований на осуществление бюджетных инвестиций в объекты государственной (муниципальной)  собственности казенных учреждений) ,  в том числе в целях: (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 07.05.2013 № 104-ФЗ; от 28.12.2013 № 418-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 13.07.2020 № 192-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nразработки,  закупки и ремонта вооружений,  военной и специальной техники,  продукции производственно-технического назначения и имущества в рамках государственного оборонного заказа;\n\nзакупки товаров в государственный материальный резерв;\n\nпредоставление субсидий юридическим лицам,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере. (Дополнение абзацем - Федеральный закон от 13.07.2020 № 192-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 69.1. Бюджетные ассигнования на оказание государственных (муниципальных)  услуг (выполнение работ)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"310cce0aa5e67d71fe6ec9b72a4b90db1dfee973446bc6ce4b809571402d7581"}]$law7d0035$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
